WITH lines AS (SELECT id, service, log_ts, level, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, attr_value) SELECT id, status_code, key, attr_value, LAG(status_code, 2) OVER (PARTITION BY level ORDER BY status_code, id, key) AS prev_status_code, LAG(status_code, 1) OVER (ORDER BY status_code, id, key) AS prev_status_code_2, SUM(status_code) OVER (PARTITION BY service ORDER BY status_code, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_code, MAX(status_code) OVER (PARTITION BY key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS status_code_max_2h, AVG(status_code) OVER w_running AS status_code_avg_5 FROM lines WINDOW w_running AS (PARTITION BY service ORDER BY log_ts, id, key ROWS BETWEEN 5 PRECEDING AND CURRENT ROW);
